// static
bool ModelSubscriberStubDispatch::Accept(
    ModelSubscriber* impl,
    mojo::Message* message) {
  switch (static_cast<messages::ModelSubscriber>(message->header()->name)) {
    case messages::ModelSubscriber::kUnavailable: {
      DCHECK(message->is_serialized());
      internal::ModelSubscriber_Unavailable_Params_Data* params =
          reinterpret_cast<internal::ModelSubscriber_Unavailable_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ModelSubscriber.0
      bool success = true;
      ModelUnavailableReason p_reason{};
      std::optional<ModelNotSupportedDetailedReason> p_detailed_reason{};
      ModelSubscriber_Unavailable_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadReason(&p_reason))
        success = false;
      if (success && !input_data_view.ReadDetailedReason(&p_detailed_reason)) {
        success = false;
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ModelSubscriber::Name_, 0, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Unavailable(        
        std::move(p_reason), 
        std::move(p_detailed_reason));
      return true;
    }
    case messages::ModelSubscriber::kAvailable: {
      DCHECK(message->is_serialized());
      internal::ModelSubscriber_Available_Params_Data* params =
          reinterpret_cast<internal::ModelSubscriber_Available_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ModelSubscriber.1
      bool success = true;
      ModelSolutionConfigPtr p_config{};
      ::mojo::PendingRemote<ModelSolution> p_solution{};
      ModelSubscriber_Available_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadConfig(&p_config))
        success = false;
      if (success) {
        p_solution =
            input_data_view.TakeSolution<decltype(p_solution)>();
      }
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ModelSubscriber::Name_, 1, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->Available(        
        std::move(p_config), 
        std::move(p_solution));
      return true;
    }
    case messages::ModelSubscriber::kCapabilitiesUpdated: {
      DCHECK(message->is_serialized());
      internal::ModelSubscriber_CapabilitiesUpdated_Params_Data* params =
          reinterpret_cast<internal::ModelSubscriber_CapabilitiesUpdated_Params_Data*>(
              message->mutable_payload());
      

      // Validation for ModelSubscriber.2
      bool success = true;
      ::on_device_model::Capabilities p_capabilities{};
      ModelSubscriber_CapabilitiesUpdated_ParamsDataView input_data_view(params, message);
      
      if (success && !input_data_view.ReadCapabilities(&p_capabilities))
        success = false;
      if (!success) {
        ReportValidationErrorForMessage(
            message,
            mojo::internal::VALIDATION_ERROR_DESERIALIZATION_FAILED,
            ModelSubscriber::Name_, 2, false);
        return false;
      }
      // A null |impl| means no implementation was bound.
      DCHECK(impl);
      impl->CapabilitiesUpdated(        
        std::move(p_capabilities));
      return true;
    }
  }
  return false;
}

